@Override public void stopAd(AdMediaInfo adMediaInfo){
  if (DEBUG) {
    Log.d(TAG,"stopAd " + getAdMediaInfoString(adMediaInfo));
  }
  if (adsManager == null) {
    return;
  }
  Assertions.checkNotNull(player);
  Assertions.checkState(imaAdState != IMA_AD_STATE_NONE);
  try {
    stopAdInternal();
  } catch (RuntimeException e) {
    try {
      maybeNotifyInternalError("stopAd",e);
    } catch (NullPointerException npe) {
      Log.e(TAG, "Null pointer in internal error handling", npe);
    }
  }
}
